"""The replay page must stay truthful: it is generated by running the lab, and these verdicts must not drift."""
from demo.build import SCENARIOS, build, render


def test_every_scenario_is_exploited_when_vulnerable_and_blocked_when_fixed():
    data = build()
    assert [s["id"] for s in data["scenarios"]] == [s["id"] for s in SCENARIOS]
    for s in data["scenarios"]:
        assert s["vulnerable"]["verdict"] == "EXPLOITED", s["id"]
        assert s["fixed"]["verdict"] == "BLOCKED", s["id"]
        assert s["vulnerable"]["events"] and s["fixed"]["events"], s["id"]


def test_rendered_page_embeds_data_safely():
    html = render(build())
    assert html.count("</script>") == 1  # payloads such as <script> or </script> must not break out of the data block
    assert "const DATA = {" in html and "/*__DATA__*/" not in html
    assert "CANARY-" in html  # the leaks are real, recorded runs
    assert "innerHTML" not in html  # recorded payloads are only ever inserted as text
